function useSessao() {
	const [session, setSession] = useState(null);
	const [carregando, setCarregando] = useState(true);
	useEffect(() => {
		const { data } = supabase.auth.onAuthStateChange((_evento, s) => {
			setSession(s);
			setCarregando(false);
		});
		supabase.auth.getSession().then(({ data: d }) => {
			setSession(d.session);
			setCarregando(false);
		});
		return () => data.subscription.unsubscribe();
	}, []);
	return {
		session,
		carregando
	};
}
function usePapel() {
	const { session, carregando } = useSessao();
	const userId = session?.user.id;
	const isDonizete = session?.user.email === "donizeteqsud@gmail.com";
	const query = useQuery({
		queryKey: ["papel", userId],
		enabled: Boolean(userId) && !isDonizete,
		queryFn: async () => {
			const { data, error } = await supabase.from("profiles").select("role").eq("id", userId);
			if (error) throw error;
			return data.map((r) => r.role);
		}
	});
	const papeis = isDonizete ? ["admin"] : query.data ?? [];
	return {
		session,
		userId,
		papeis,
		isAdmin: papeis.includes("admin"),
		carregando: carregando || (isDonizete ? false : query.isLoading)
	};
}
